// Verify the HMAC before reading the payload or doing any work.
// Canonical message: `${timestamp}.${rawBody}` (matches Convex lib/hmac.ts).
const crypto = require('crypto');

const item = $input.first().json;
const headers = item.headers || {};
const header = (name) => {
  const key = Object.keys(headers).find((candidate) => candidate.toLowerCase() === name);
  return key ? headers[key] : undefined;
};

const rawBody =
  typeof item.body === 'string'
    ? item.body
    : typeof Buffer !== "undefined" && Buffer.isBuffer(item.body)
      ? item.body.toString('utf8')
      : JSON.stringify(item.body ?? {});

const timestamp = String(header('x-lendloop-timestamp') || '');
const provided = String(header('x-lendloop-signature') || '')
  .trim()
  .toLowerCase()
  .replace(/^sha256=/, '');
const secret = $env.LENDLOOP_HMAC_SECRET;

if (!secret) {
  return [{ json: { valid: false, reason: 'missing_secret' } }];
}
if (!/^\d{1,12}$/.test(timestamp)) {
  return [{ json: { valid: false, reason: 'invalid_timestamp' } }];
}

const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - Number(timestamp)) > 300) {
  return [{ json: { valid: false, reason: 'stale_timestamp' } }];
}
if (!/^[0-9a-f]{64}$/.test(provided)) {
  return [{ json: { valid: false, reason: 'invalid_signature_format' } }];
}

const expected = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

const expectedBuffer = Buffer.from(expected, 'utf8');
const providedBuffer = Buffer.from(provided, 'utf8');
const valid =
  expectedBuffer.length === providedBuffer.length &&
  crypto.timingSafeEqual(expectedBuffer, providedBuffer);

if (!valid) {
  return [{ json: { valid: false, reason: 'invalid_signature' } }];
}

let payload;
try {
  payload = JSON.parse(rawBody);
} catch {
  return [{ json: { valid: false, reason: 'invalid_json' } }];
}

return [{ json: { valid: true, payload } }];

// Rebuild the payload explicitly. Unknown fields are dropped (data minimisation).
const events = ['requested', 'approved', 'declined', 'returned'];
const p = $json.payload;

const text = (value, max) => {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (!trimmed || trimmed.length > max) return null;
  return trimmed;
};
const date = (value) => (typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null);

const event = typeof p?.event === 'string' && events.includes(p.event) ? p.event : null;
const loanId = text(p?.loanId, 64);
const toolName = text(p?.toolName, 80);
const startDate = date(p?.startDate);
const endDate = date(p?.endDate);
const recipientName = text(p?.recipient?.firstName, 80);
const recipientEmail = text(p?.recipient?.email, 254);
const counterpartyName = text(p?.counterpartyFirstName, 80);

if (!event || !loanId || !toolName || !startDate || !endDate) {
  throw new Error('Invalid loan event payload: missing required fields');
}
if (!recipientEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipientEmail)) {
  throw new Error('Invalid loan event payload: recipient email');
}

return [
  {
    json: {
      event,
      loanId,
      toolName,
      startDate,
      endDate,
      recipient: { firstName: recipientName || 'Neighbor', email: recipientEmail },
      counterpartyFirstName: counterpartyName || 'Neighbor',
    },
  },
];

// Mock delivery: a logged notification is explicitly acceptable for this task.
// Swap this node for an Email/Slack node to deliver for real (see README).
const n = $json;
const labels = {
  requested: 'new borrow request',
  approved: 'request approved',
  declined: 'request declined',
  returned: 'tool returned',
};
const subject = `LendLoop: ${labels[n.event]} — ${n.toolName}`;
const body =
  n.event === 'requested'
    ? `Hi ${n.recipient.firstName}, ${n.counterpartyFirstName} would like to borrow your ${n.toolName} from ${n.startDate} to ${n.endDate}.`
    : `Hi ${n.recipient.firstName}, your request for ${n.toolName} (${n.startDate} to ${n.endDate}) is now ${n.event}.`;

const [localPart, domain] = n.recipient.email.split('@');
const maskedEmail = `${localPart.slice(0, 1)}***@${domain}`;
console.log(`[LendLoop][notification] ${subject} -> ${maskedEmail}`);

return [{ json: { ok: true, event: n.event, loanId: n.loanId, channel: 'log' } }];
